export const dynamic = 'force-dynamic'

/**
 * POST /api/cron/reconcile-mpesa
 *
 * Reconciles M-Pesa STK Push payments that never received a callback.
 *
 * Why: if the customer closes the browser before the STK callback arrives
 * (or Safaricom's callback fails), the payment row stays `pending` forever —
 * the customer may have paid but their subscription never activates, and
 * there is no audit trail. This job asks Daraja's STK Push Query API for an
 * authoritative answer and finalizes each row accordingly.
 *
 * Designed to be called every 5 minutes by cron / scheduled workflow:
 *   Auth: Bearer API_ADMIN_KEY (same pattern as trial-reminders).
 *
 * Finalization rules per stale pending payment (older than RECONCILE_AFTER_MIN):
 *   - Daraja ResultCode 0            → completed + activate subscription
 *   - Daraja definitive failure code → failed
 *   - query error / ambiguous        → leave pending, retry next run
 *   - older than ABANDON_AFTER_HRS   → marked failed without querying
 */

import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { getMpesaService } from '@/lib/payments/mpesa'
import { logger } from '@/lib/logger'
import type { PlanId } from '@/lib/subscription/catalog'

const RECONCILE_AFTER_MIN = 15
const ABANDON_AFTER_HRS = 48
const MAX_BATCH = 50

interface StalePaymentRow {
  id: string
  user_id: string
  plan_id: string | null
  currency: string | null
  amount: number | null
  transaction_id: string | null
}

export async function POST(req: NextRequest) {
  const authHeader = req.headers.get('authorization')
  const serviceKey = process.env.API_ADMIN_KEY
  if (!serviceKey || authHeader !== `Bearer ${serviceKey}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const mpesa = getMpesaService()
  if (!mpesa) {
    return NextResponse.json(
      { skipped: true, reason: 'M-Pesa not configured' },
      { status: 200 },
    )
  }

  const { rows: stale } = await db.query<StalePaymentRow>(
    `SELECT id, user_id, plan_id, currency, amount, transaction_id
     FROM payment_history
     WHERE provider = 'mpesa'
       AND status = 'pending'
       AND transaction_id IS NOT NULL
       AND created_at < NOW() - make_interval(mins => $1)
     ORDER BY created_at ASC
     LIMIT $2`,
    [RECONCILE_AFTER_MIN, MAX_BATCH],
  )

  let completed = 0
  let failed = 0
  let keptPending = 0
  const errors: Array<{ id: string; error: string }> = []

  for (const pay of stale) {
    try {
      // Abandoned checkouts: finalize without hitting Daraja.
      const { rows: ageRows } = await db.query<{ old: boolean }>(
        `SELECT created_at < NOW() - make_interval(hours => $1) AS old FROM payment_history WHERE id = $2`,
        [ABANDON_AFTER_HRS, pay.id],
      )
      if (ageRows[0]?.old) {
        await db.query(`UPDATE payment_history SET status = 'failed', metadata = COALESCE(metadata,'{}'::jsonb) || '{"reconciled":"abandoned_timeout"}'::jsonb WHERE id = $1`, [pay.id])
        failed++
        continue
      }

      const result = await mpesa.checkTransactionStatus(pay.transaction_id!)

      if (result.status === 'completed') {
        await db.query(
          `UPDATE payment_history SET status = 'completed',
              metadata = COALESCE(metadata,'{}'::jsonb) || '{"reconciled":true}'::jsonb
            WHERE id = $1 AND status = 'pending'`,
          [pay.id],
        )
        await activateSubscriptionForReconciliation(pay)
        completed++
      } else if (typeof result.resultCode === 'number' && result.resultCode !== 0) {
        // Definitive failure from Daraja (cancelled, timeout, insufficient funds…)
        await db.query(
          `UPDATE payment_history SET status = 'failed',
              metadata = COALESCE(metadata,'{}'::jsonb) || $2::jsonb
            WHERE id = $1 AND status = 'pending'`,
          [pay.id, JSON.stringify({ reconciled: true, resultCode: result.resultCode, resultDesc: result.resultDesc })],
        )
        failed++
      } else {
        // Ambiguous (query endpoint hiccup) — leave pending for the next run.
        keptPending++
      }
    } catch (err: unknown) {
      keptPending++
      errors.push({ id: pay.id, error: (err as Error).message })
    }
  }

  logger.info('[cron/reconcile-mpesa] run complete', { stale: stale.length, completed, failed, keptPending })

  return NextResponse.json({
    ok: true,
    scanned: stale.length,
    completed,
    failed,
    keptPending,
    ...(errors.length > 0 && { errors }),
  })
}

/** Mirror of the callback route's activation block, scoped to one payment. */
async function activateSubscriptionForReconciliation(pay: StalePaymentRow): Promise<void> {
  const existingSub = await db.query<{ id: string }>(
    'SELECT id FROM user_subscriptions WHERE user_id = $1',
    [pay.user_id],
  )
  const periodStart = new Date().toISOString()
  const periodEnd = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()

  if (existingSub.rows.length > 0) {
    await db.query(
      `UPDATE user_subscriptions
         SET plan_id = $1, status = 'active', payment_method = 'mpesa',
             currency = 'KES', current_period_start = $2, current_period_end = $3
         WHERE id = $4`,
      [(pay.plan_id as PlanId) || 'pro', periodStart, periodEnd, existingSub.rows[0].id],
    )
  } else {
    await db.query(
      `INSERT INTO user_subscriptions
         (user_id, plan_id, status, payment_method, currency,
          current_period_start, current_period_end)
       VALUES ($1, $2, 'active', 'mpesa', 'KES', $3, $4)`,
      [pay.user_id, (pay.plan_id as PlanId) || 'pro', periodStart, periodEnd],
    )
  }
}

'use client';

import { Suspense, useEffect, useMemo, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import type { CurrencyCode, PlanId } from '@/lib/subscription/catalog'
import { PLAN_CATALOG } from '@/lib/subscription/catalog'
import {
  checkMpesaPaymentStatus,
  getCurrencyForCountry,
  getPaymentMethods,
  startSubscriptionPayment,
  type PaymentMethod,
} from '@/lib/enterprise'

// PayPal only supports these currencies
const PAYPAL_CURRENCIES = new Set(['USD', 'EUR', 'GBP', 'AUD', 'CAD', 'CHF', 'CZK', 'DKK', 'HKD', 'HUF', 'ILS', 'JPY', 'MXN', 'NOK', 'NZD', 'PHP', 'PLN', 'SEK', 'SGD', 'THB', 'TWD'])

function CheckoutContent() {
  const searchParams = useSearchParams()
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1)
  const [selectedPlanId, setSelectedPlanId] = useState<PlanId>(() => {
    const planParam = searchParams.get('plan') as PlanId | null
    if (planParam && PLAN_CATALOG.some(p => p.id === planParam)) return planParam
    return 'pro'
  })
  const [country, setCountry] = useState('Kenya')
  const [currency, setCurrency] = useState<CurrencyCode>('KES')
  const [method, setMethod] = useState<PaymentMethod['type']>('mpesa')
  const [phoneNumber, setPhoneNumber] = useState('')
  const [email, setEmail] = useState('')
  const [processing, setProcessing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [mpesa, setMpesa] = useState<{ paymentId: string; checkoutRequestId: string } | null>(null)

  const plan = useMemo(
    () => PLAN_CATALOG.find((p) => p.id === selectedPlanId) ?? PLAN_CATALOG[0],
    [selectedPlanId]
  )

  const paymentMethods = useMemo(() => getPaymentMethods(country), [country])

  useEffect(() => {
    if (!paymentMethods.some((m) => m.type === method)) {
      setMethod(paymentMethods[0]?.type ?? 'card')
    }
  }, [paymentMethods, method])

  // ─── M-Pesa auto-polling (step 4) ────────────────────────────────────────
  // Poll the authoritative Daraja status every 4s while the customer is on
  // the "STK Push Sent" screen, so the plan activates the moment they enter
  // their PIN — without them having to press "Verify Payment". Stops on a
  // terminal status or after ~3 minutes (the manual button still works).
  const [autoPollCount, setAutoPollCount] = useState(0)
  const [autoVerifying, setAutoVerifying] = useState(false)
  useEffect(() => {
    if (step !== 4 || !mpesa) return
    setAutoPollCount(0)
    let cancelled = false
    const MAX_POLLS = 45 // 45 × 4s ≈ 3 minutes

    const tick = async () => {
      if (cancelled) return
      setAutoVerifying(true)
      try {
        const r = await checkMpesaPaymentStatus(mpesa)
        if (cancelled) return
        if (r.status === 'completed') {
          window.location.href = '/dashboard'
          return
        }
        if (r.status === 'failed') {
          setError('Payment failed. Please try again.')
          return
        }
      } catch {
        // Transient network/Daraja errors — keep polling quietly.
      } finally {
        if (!cancelled) setAutoVerifying(false)
      }
    }

    const interval = setInterval(() => {
      setAutoPollCount((c) => {
        if (c >= MAX_POLLS) {
          clearInterval(interval)
          return c
        }
        void tick()
        return c + 1
      })
    }, 4000)

    return () => {
      cancelled = true
      clearInterval(interval)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, mpesa?.paymentId, mpesa?.checkoutRequestId])


  const formatPrice = (amount: number) => {
    const symbols: Partial<Record<CurrencyCode, string>> = {
      KES: 'KSh ',
      UGX: 'USh ',
      TZS: 'TSh ',
      NGN: '₦ ',
      GHS: 'GH₵ ',
      ZAR: 'R ',
      USD: '$ ',
      EUR: '€ ',
      GBP: '£ ',
      INR: '₹ ',
      IDR: 'Rp ',
      BRL: 'R$ ',
      AUD: 'A$ ',
    }
    return `${symbols[currency] ?? `${currency} `}${amount.toLocaleString()}`
  }

  const onStart = async () => {
    setError(null)
    setProcessing(true)
    try {
      const res = await startSubscriptionPayment({
        planId: plan.id,
        currency,
        method,
        email,
        phoneNumber: phoneNumber || undefined,
        country,
      })

      if (res.kind === 'activated') {
        window.location.href = '/dashboard'
        return
      }

      if (res.kind === 'redirect') {
        window.location.href = res.url
        return
      }

      if (res.kind === 'mpesa') {
        setMpesa({ paymentId: res.paymentId, checkoutRequestId: res.checkoutRequestId })
        setStep(4)
        return
      }

      setError('Unexpected payment response.')
    } catch (e: unknown) {
      setError(((e as Error)?.message) ?? 'Payment failed.')
    } finally {
      setProcessing(false)
    }
  }

  const canContinueDetails =
    !!email && (method !== 'mpesa' || !!phoneNumber) && paymentMethods.some((m) => m.type === method)

  return (
    <div className="min-h-screen">
      <div className="max-w-4xl mx-auto px-4 py-8 md:py-10">
        <h1 className="text-2xl md:text-3xl font-bold text-[var(--text-primary)] mb-2">Checkout</h1>
        <p className="text-[var(--text-secondary)] mb-8">Choose a plan and complete payment.</p>

        <div className="flex gap-2 mb-8">
          {[1, 2, 3].map((s) => (
            <div
              key={s}
              className={`flex-1 h-2 rounded ${step >= s ? 'bg-[var(--accent)]' : 'bg-[var(--bg-tertiary)]'}`}
            />
          ))}
        </div>

        {error && (
          <div className="mb-6 rounded-lg border border-red-900/50 bg-red-900/10 px-4 py-3 text-sm text-red-200">
            {error}
          </div>
        )}

        {step === 1 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">1) Select Plan</h2>

            <div className="mb-4">
              <label htmlFor="checkout-country" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Country</label>
              <select
                id="checkout-country"
                value={country}
                onChange={(e) => {
                  const c = e.target.value
                  setCountry(c)
                  setCurrency(getCurrencyForCountry(c))
                }}
                className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
              >
                <option value="Kenya">Kenya</option>
                <option value="Uganda">Uganda</option>
                <option value="Tanzania">Tanzania</option>
                <option value="Nigeria">Nigeria</option>
                <option value="Ghana">Ghana</option>
                <option value="South Africa">South Africa</option>
                <option value="Germany">Germany</option>
                <option value="UK">UK</option>
                <option value="US">US</option>
              </select>
              <p className="text-xs text-[var(--text-muted)] mt-2">Currency auto-selects from country, and you can still pay via card globally.</p>
            </div>

            <div className="space-y-3">
              {PLAN_CATALOG.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => setSelectedPlanId(p.id)}
                  className={`w-full text-left p-4 border-2 rounded-lg transition min-h-[56px] ${
                    selectedPlanId === p.id ? 'border-[var(--accent)] bg-[color-mix(in_srgb,var(--accent)_10%,transparent)]' : 'border-[var(--border-color)] hover:border-[var(--border-hover)]'
                  }`}
                >
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <div className="text-[var(--text-primary)] font-semibold text-lg">{p.name}</div>
                      <div className="text-[var(--text-muted)] text-sm">{p.features.slice(0, 2).join(' • ')}</div>
                    </div>
                    <div className="text-right">
                      <div className="text-[var(--accent)] font-bold text-2xl">{formatPrice(p.prices[currency])}</div>
                      <div className="text-[var(--text-muted)] text-xs">/month</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>

            <button
              onClick={() => setStep(2)}
              className="w-full mt-6 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-medium min-h-[44px]"
            >
              Continue
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">2) Payment Details</h2>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="checkout-email" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Email</label>
                <input
                  id="checkout-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
              </div>
              <div>
                <label htmlFor="checkout-phone" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Phone (M-Pesa only)</label>
                <input
                  id="checkout-phone"
                  type="tel"
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  placeholder="e.g. 254712345678"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
                <p className="text-xs text-[var(--text-muted)] mt-2">Required only for M-Pesa STK Push.</p>
              </div>
            </div>

            <div className="mt-6">
              <div className="block text-sm font-medium text-[var(--text-primary)] mb-2">Payment Method</div>
              <div className="space-y-2">
                {paymentMethods.map((pm) => (
                  <label
                    key={pm.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer min-h-[44px] ${
                      method === pm.type ? 'border-[var(--accent)] bg-[color-mix(in_srgb,var(--accent)_10%,transparent)]' : 'border-[var(--border-color)]'
                    }`}
                  >
                    <input aria-label="Paymentmethod"
                      type="radio"
                      name="paymentMethod"
                      value={pm.type}
                      checked={method === pm.type}
                      onChange={() => setMethod(pm.type)}
                    />
                    <span className="text-[var(--text-primary)]">{pm.name}</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setStep(1)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={() => setStep(3)}
                disabled={!canContinueDetails}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                Review Order
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">3) Confirm & Pay</h2>

            <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-primary)] p-4 mb-6">
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Plan</span>
                <span className="font-semibold">{plan.name}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Currency</span>
                <span className="font-semibold">{currency}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Method</span>
                <span className="font-semibold">{paymentMethods.find((p) => p.type === method)?.name ?? method}</span>
              </div>
              <div className="flex items-center justify-between border-t border-[var(--border-color)] pt-2 mt-2 text-[var(--text-primary)]">
                <span className="font-semibold">Total</span>
                <span className="font-bold text-lg text-[var(--accent)]">{formatPrice(plan.prices[currency])}</span>
              </div>
            </div>

            <div className="text-xs text-[var(--text-muted)] mb-6">
              Card payments use Stripe Checkout (Visa/Mastercard). PayPal redirects to PayPal approval. M-Pesa triggers STK push.
              {method === 'paypal' && !PAYPAL_CURRENCIES.has(currency) && (
                <span className="block mt-2 text-amber-400">
                  PayPal does not support {currency}. You will be charged the USD equivalent.
                </span>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setStep(2)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={onStart}
                disabled={processing}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                {processing ? 'Starting payment…' : 'Pay Now'}
              </button>
            </div>
          </div>
        )}

        {step === 4 && mpesa && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-2">M-Pesa STK Push Sent</h2>
            <p className="text-[var(--text-secondary)] mb-2">Enter your M-Pesa PIN on your phone. This page activates your plan automatically once the payment is confirmed.</p>
            <p className="text-xs text-[var(--text-secondary)] mb-6 flex items-center gap-2">
              {autoVerifying && (
                <span className="inline-block w-2 h-2 rounded-full bg-[var(--accent)] animate-pulse" aria-hidden="true" />
              )}
              {autoVerifying ? 'Verifying payment…' : 'Waiting for confirmation…'}
            </p>

            <button
              onClick={async () => {
                setProcessing(true)
                setError(null)
                try {
                  const r = await checkMpesaPaymentStatus(mpesa)
                  if (r.status === 'completed') {
                    window.location.href = '/dashboard'
                    return
                  }
                  if (r.status === 'failed') setError('Payment failed. Please try again.')
                  if (r.status === 'pending') setError('Still pending. If you have paid, wait a moment then try again.')
                } catch (e: unknown) {
                  setError(((e as Error)?.message) ?? 'Failed to verify payment.')
                } finally {
                  setProcessing(false)
                }
              }}
              disabled={processing}
              className="w-full py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
            >
              {processing ? 'Checking…' : 'Verify Payment'}
            </button>

            <button
              onClick={() => {
                setMpesa(null)
                setStep(2)
              }}
              className="w-full mt-3 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
            >
              Change method
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

export default function CheckoutPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <CheckoutContent />
    </Suspense>
  )
}

'use client'
/**
 * METARDU Global Map Page — Premium OpenLayers Interface
 *
 * ┌──────────────────────────────────────────────────────────────┐
 * │  ARCHITECTURE: Split into sub-components for maintainability │
 * │                                                              │
 * │  MapClient.tsx    → Orchestrator (state + wiring)           │
 * │  ├─ hooks/useMapInit.ts        → Map initialization         │
 * │  ├─ hooks/useMapBasemaps.ts    → Basemap layer management   │
 * │  ├─ hooks/useMapState.ts       → View persistence           │
 * │  ├─ hooks/useMapInteractions.ts → Draw/Measure/GPS/Export   │
 * │  ├─ components/MapToolbar.tsx   → Left sidebar (context)    │
 * │  ├─ components/MapOverlays.tsx  → Zoom/GPS/Stakeout (ctx)   │
 * │  ├─ components/MapStatusBar.tsx → Bottom coord bar (ctx)    │
 * │  ├─ components/MapLoadingOverlay.tsx → Loading/Error (ctx)  │
 * │  ├─ components/MapNotifications.tsx  → Toast (context)      │
 * │  ├─ components/MapCoordSearch.tsx   → Coord search (ctx)    │
 * │  ├─ components/CogoInfoPanel.tsx    → COGO traverse (ctx)   │
 * │  ├─ components/CogoToolsPanel.tsx   → COGO compute (ctx)    │
 * │  ├─ components/RotationControl.tsx  → North arrow reset     │
 * │  ├─ components/MapPrintButton.tsx   → Print button (ctx)    │
 * │  ├─ LayerControl (reusable, props)  → Grid/XYZ/WMS/Opacity │
 * │  ├─ VertexEditToolbar (ctx version) → Vertex editing + snap │
 * │  ├─ ProjectionSwitcher (context)    → CRS switching         │
 * │  ├─ StakeoutPanel (context)         → GPS stakeout HUD      │
 * │  ├─ SchemeLayerPanel (context)      → Scheme layer controls │
 * │  ├─ OfflineTileDownloader (context) → Offline tile dialog   │
 * │  ├─ SheetLayout (dynamic)           → Print layout overlay  │
 * │  └─ MapReactContext                 → Zero-prop data bus    │
 * │                                                              │
 * │  Performance optimizations:                                  │
 * │  - All sub-components wrapped in React.memo                 │
 * │  - useMemo for stable object references                     │
 * │  - useCallback for all interaction handlers                 │
 * │  - 100ms mouse position throttle                            │
 * │  - Dynamic imports for all OpenLayers modules               │
 * │  - Tile cache size 2048 for all basemaps                    │
 * │  - Map state persistence every 10s (not per move)           │
 * │  - Safety timeout: force ready after 5s                     │
 * └──────────────────────────────────────────────────────────────┘
 *
 * Features:
 *  - Draw interaction (Point, Line, Polygon, Circle)
 *  - Modify interaction (vertex editing)
 *  - Select interaction + Popup overlays
 *  - Undo / Redo history (via useMapHistory hook)
 *  - Measurement (Distance & Area with bearing)
 *  - GeoJSON / KML / WKT import & export (DXF/LandXML export only — no import)
 *  - Drag & Drop file import
 *  - MousePosition (live EPSG:21037 coords)
 *  - Geolocation (GPS tracking)
 *  - GPS Stakeout mode (Pro+)
 *  - Cluster source for project markers
 *  - Multiple basemaps (OSM, Satellite, Dark, Terrain)
 *  - Bearing/distance annotations on drawn features
 *  - Save drawn features to project
 *  - Offline tile download (Pro+)
 *  - URL param ?projectId=xxx deep linking
 *  - Keyboard shortcuts (Ctrl+Z/Y, Del, Esc)
 *  - Map state persistence (localStorage)
 *  - Coordinate search (lat/lon, UTM, DMS)
 */

