      projectPointsCleanupRef.current = result.cleanup
      projectPointsLayerRef.current = result.pointsLayer
      setProjectPointsCount(result.pointCount)
    } catch (err) {
      logger.error('[MapClient] Failed to load project points:', { error: err })
