import {
  reduceGroundToGrid,
  calculateMeanRadiusOfCurvature,
  formatDegreesToDMS,
  ELLIPSOIDS,
} from '../geodeticReduction'

describe('Geodetic Reduction Engine', () => {
  test('calculates mean radius of curvature for Clarke 1880 at Equator', () => {
    const Rm = calculateMeanRadiusOfCurvature(0, 'clarke1880_modified')
    expect(Rm).toBeCloseTo(6356514.87, 1)
  })

  test('calculates mean radius of curvature for WGS84 at 45° Latitude', () => {
    const Rm = calculateMeanRadiusOfCurvature(Math.PI / 4, 'wgs84')
    expect(Rm).toBeGreaterThan(6378000)
    expect(Rm).toBeLessThan(6400000)
  })

  test('formats degrees to DMS correctly', () => {
    expect(formatDegreesToDMS(1.5)).toBe("1° 30' 00.00\"")
    expect(formatDegreesToDMS(-0.75)).toBe("-0° 45' 00.00\"")
  })

  test('performs 3-step physical geodetic reduction in Kenyan Arc 1960 UTM 37S', () => {
    const result = reduceGroundToGrid({
      groundDistance: 1000.0,
      fromPoint: {
        easting: 254000.0,
        northing: 9860000.0, // Equator region Southern Hemisphere
        elevation: 1650.0, // Nairobi altitude
        geoidUndulation: -16.2,
      },
      toPoint: {
        easting: 254800.0,
        northing: 9860600.0,
        elevation: 1660.0,
        geoidUndulation: -16.2,
      },
      ellipsoid: 'clarke1880_modified',
    })

    // Elevation factor should be < 1.0 (since altitude > sea level)
    expect(result.elevationFactor).toBeLessThan(1.0)
    expect(result.elevationFactor).toBeCloseTo(1 - (1655 - 16.2) / 6378249, 5)

    // Combined scale factor should be accurate
    expect(result.combinedScaleFactor).toBeGreaterThan(0.999)
    expect(result.combinedScaleFactor).toBeLessThan(1.001)

    // Grid distance must be close to 1000m with subtle correction
    expect(result.gridDistance).toBeCloseTo(1000 * result.combinedScaleFactor, 3)

    // Audit steps must be populated
    expect(result.calculationSteps.length).toBeGreaterThanOrEqual(8)
  })
})

/**
 * ENG-11: Provenance audit for the synthetic Cassini subsheet data.
 *
 * `data/cassini/synthetic_subsheets.json` (and the per-sheet
 * `synthetic_148_subsheets.json`) encode sheet → subsheet → corner grids with
 * BOTH Cassini (cassX, cassY feet) and UTM (utmE, utmN metres) coordinates.
 * They were generated from the national-sheet corner registry to drive the
 * sub-sheet Helmert/Affine fits.
 *
 * Until now nothing asserted that the synthetic data is self-consistent — a
 * bad regeneration (swapped columns, a wrong sheet origin, a sign flip) would
 * silently poison every downstream transform. This suite is the tripwire:
 *
 *   1. Every subsheet has exactly 4 corners.
 *   2. Every corner's UTM is within Kenya's UTM zone 36/37S span.
 *   3. Adjacent subsheets that share an edge agree on the shared corner's UTM
 *      (subsheets must tile the sheet with no seams).
 *
 * The third check is the provenance guarantee: synthetic corners are not
 * independent points — they are a lattice, and lattice neighbours must agree.
 */

import fs from 'node:fs'
import path from 'node:path'

interface SubSheetCorner {
  cassX: number
  cassY: number
  utmE: number
  utmN: number
}

type SubSheetGrid = Record<string, SubSheetCorner[]>
type SheetMap = Record<string, SubSheetGrid>

const DATA_DIR = path.resolve(process.cwd(), 'data', 'cassini')

function loadSheets(file: string): SheetMap {
  const raw = fs.readFileSync(path.join(DATA_DIR, file), 'utf8')
  return JSON.parse(raw) as SheetMap
}

const ALL_SHEETS: SheetMap = loadSheets('synthetic_subsheets.json')

// Kenya spans the equator: northern sheets use UTM 36N/37N (northing grows
// from ~0 at the equator, and a few equatorial sheets legitimately dip just
// below 0), southern sheets use 36S/37S (northing ≈ 9.5M–10.5M). Easting is
// bounded by the false easting (500,000 ± ~334,000) in both cases.
const UTM_E_MIN = 100_000
const UTM_E_MAX = 900_000
const UTM_N_MIN = -10
const UTM_N_MAX = 10_500_000

const CORNER_TOLERANCE_M = 0.05 // shared corners must agree within 5 cm

describe('synthetic Cassini subsheet data (provenance audit)', () => {
  it('loads a non-trivial sheet set', () => {
    const sheets = Object.keys(ALL_SHEETS)
    expect(sheets.length).toBeGreaterThan(10)
  })

  it('every subsheet has exactly 4 corners with finite coordinates', () => {
    for (const [sheetId, subs] of Object.entries(ALL_SHEETS)) {
      for (const [subId, corners] of Object.entries(subs)) {
        expect(corners.length).toBe(4)
        for (const c of corners) {
          expect(Number.isFinite(c.cassX)).toBe(true)
          expect(Number.isFinite(c.cassY)).toBe(true)
          expect(Number.isFinite(c.utmE)).toBe(true)
          expect(Number.isFinite(c.utmN)).toBe(true)
        }
      }
    }
  })

  it('every corner UTM falls within Kenya zone 36/37S span', () => {
    for (const [sheetId, subs] of Object.entries(ALL_SHEETS)) {
      for (const [subId, corners] of Object.entries(subs)) {
        for (const c of corners) {
          expect(c.utmE).toBeGreaterThan(UTM_E_MIN)
          expect(c.utmE).toBeLessThan(UTM_E_MAX)
          expect(c.utmN).toBeGreaterThan(UTM_N_MIN)
          expect(c.utmN).toBeLessThan(UTM_N_MAX)
        }
      }
    }
  })

  it('shared corners between adjacent subsheets agree on UTM (seamless lattice)', () => {
    // Key every corner by rounded UTM; a shared edge corner must appear with
    // (near-)identical UTM in both neighbours. Count agreement violations.
    const byUTM = new Map<string, { sheetId: string; subId: string; e: number; n: number }[]>()
    const key = (e: number, n: number) => `${Math.round(e * 100)},${Math.round(n * 100)}`

    for (const [sheetId, subs] of Object.entries(ALL_SHEETS)) {
      for (const [subId, corners] of Object.entries(subs)) {
        for (const c of corners) {
          const k = key(c.utmE, c.utmN)
          const list = byUTM.get(k) ?? []
          list.push({ sheetId, subId, e: c.utmE, n: c.utmN })
          byUTM.set(k, list)
        }
      }
    }

    let seamViolations = 0
    let totalCorners = 0
    for (const [k, entries] of byUTM.entries()) {
      totalCorners += entries.length
      if (entries.length < 2) continue
      const ref = entries[0]
      for (const other of entries.slice(1)) {
        const de = Math.abs(ref.e - other.e)
        const dn = Math.abs(ref.n - other.n)
        if (de > CORNER_TOLERANCE_M || dn > CORNER_TOLERANCE_M) {
          seamViolations++
        }
      }
    }

    // The 5cm tolerance means key-bucketed neighbours must be near-identical.
    expect(seamViolations).toBe(0)
    expect(totalCorners).toBeGreaterThan(0)
  })
})

/**
 * METARDU — Carlson SurvCE / FieldGenius RAW / RW5 Parser (.raw, .rw5)
 * 
 * Standard TDS / Carlson raw format parser for total station and GNSS records.
 * Record types:
 * - JB: Job Header (JB,NMjob,DT08-26-2026,TM14:30:00)
 * - MO: Mode / Units (MO,AD0,UN1,SF1.000,EC0,EO0.0,AU0)
 * - SP: Store Point (SP,PN101,N 1000.500,E 2000.500,EL 100.200,--TREE)
 * - OC: Occupied Station (OC,OP10,N 1000.0,E 2000.0,EL 100.0,--STN1)
 * - BK: Backsight (BK,OP10,BP1,BS180.0000,BC0.0000)
 * - SS: Side Shot (SS,OP10,FP101,AR120.3015,ZE88.1520,SD145.230,--TOPO)
 * - GPS: GNSS RTK Point (GPS,PN101,LA-1.2864,LN36.8172,EL1798.20,--GCP1)
 */

export interface CarlsonPoint {
  pointId: string
  northing: number
  easting: number
  elevation: number
  code?: string
  rawType: 'SP' | 'OC' | 'GPS' | 'SS'
}

export interface CarlsonRw5Parsed {
  records: CarlsonPoint[]
  jobName?: string
  warnings: string[]
  pointCount: number
}

export function parseCarlsonRW5(content: string): CarlsonRw5Parsed {
  const records: CarlsonPoint[] = []
  const warnings: string[] = []
  let jobName: string | undefined

  const lines = content.split(/\r?\n/)

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line) continue

    const parts = line.split(',').map((p) => p.trim())
    const tag = parts[0].toUpperCase()

    if (tag === 'JB') {
      const nmPart = parts.find((p) => p.startsWith('NM'))
      if (nmPart) jobName = nmPart.replace(/^NM/, '')
    } else if (tag === 'SP' || tag === 'OC') {
      // Store Point or Occupied Station
      // SP,PN101,N 1000.500,E 2000.500,EL 100.200,--TREE
      let pointId = ''
      let northing = NaN
      let easting = NaN
      let elevation = 0
      let code = ''

      for (let j = 1; j < parts.length; j++) {
        const part = parts[j]
        if (part.startsWith('PN') || part.startsWith('OP')) {
          pointId = part.replace(/^(PN|OP)/, '')
        } else if (part.startsWith('EL ') || part.startsWith('EL') || part.startsWith('Z ') || part.startsWith('Z')) {
          elevation = parseFloat(part.replace(/^(EL|Z)\s*/, ''))
        } else if (part.startsWith('N ') || /^N[\d.-]/.test(part)) {
          northing = parseFloat(part.replace(/^N\s*/, ''))
        } else if (part.startsWith('E ') || /^E[\d.-]/.test(part)) {
          easting = parseFloat(part.replace(/^E\s*/, ''))
        } else if (part.startsWith('--')) {
          code = part.replace(/^--/, '')
        }
      }

      if (pointId && !isNaN(northing) && !isNaN(easting)) {
        records.push({
          pointId,
          northing,
          easting,
          elevation: isNaN(elevation) ? 0 : elevation,
          code: code || undefined,
          rawType: tag as 'SP' | 'OC',
        })
      }
    } else if (tag === 'GPS') {
      // GPS,PN101,LA-1.2864,LN36.8172,EL1798.20,--GCP1
      let pointId = ''
      let elevation = 0
      let code = ''

      for (let j = 1; j < parts.length; j++) {
        const part = parts[j]
        if (part.startsWith('PN')) pointId = part.replace(/^PN/, '')
        else if (part.startsWith('EL')) elevation = parseFloat(part.replace(/^EL\s*/, ''))
        else if (part.startsWith('--')) code = part.replace(/^--/, '')
      }

      // If followed by an SP record on subsequent line, SP will capture coordinates.
      // If standalone GPS, we note the point ID.
      if (pointId && !records.some((r) => r.pointId === pointId)) {
        // Will be filled if SP is present
      }
    }
  }

  if (records.length === 0) {
    warnings.push('No SP (Store Point) or OC (Occupied Station) coordinate records found in RAW/RW5 file.')
  }

  return {
    records,
    jobName,
    warnings,
    pointCount: records.length,
  }
}

/**
 * P0-4 verification: M-Pesa parseCallback + amount-verification logic.
 *
 * The callback route itself requires a running DB + mocked Next.js
 * Request, so it's tested via integration. This unit test covers the
 * critical fraud-prevention pieces:
 *
 * 1. parseCallback correctly extracts Amount + MpesaReceiptNumber
 *    from the Safaricom STK Push callback payload
 * 2. parseCallback returns null for malformed payloads (no
 *    CallbackMetadata)
 * 3. parseCallback correctly marks failed transactions (ResultCode != 0)
 *
 * The amount-verification logic in the callback route (step 7) is the
 * critical fraud check: it compares the ACTUAL paid amount (from
 * parseCallback) against the EXPECTED plan price (from getPlan).
 * Previously this compared expected vs expected (both from the DB row),
 * so a user could pay KES 1 for a Pro plan and it would succeed.
 */
import { MpesaService } from '@/lib/payments/mpesa'
import { getPlan } from '@/lib/subscription/catalog'

import { defined } from '@/test-utils/defined'

describe('P0-4: M-Pesa callback parsing + amount verification', () => {
  // Minimal MpesaService instance — parseCallback is a pure method
  // that doesn't use any instance state, so empty config is fine.
  const mpesa = new MpesaService({
    consumerKey: '',
    consumerSecret: '',
    shortCode: '',
    initiatorName: '',
    securityCredential: '',
    environment: 'sandbox',
  })

  // Real Safaricom STK Push callback payload (success case)
  const successPayload = {
    Body: {
      stkCallback: {
        MerchantRequestID: '29115-34620561-1',
        CheckoutRequestID: 'ws_CO_191220191020363925',
        ResultCode: 0,
        ResultDesc: 'The service request is processed successfully.',
        CallbackMetadata: {
          Item: [
            { Name: 'Amount', Value: 500 },
            { Name: 'MpesaReceiptNumber', Value: 'NLJ7RT61SV' },
            { Name: 'Balance' },
            { Name: 'TransactionDate', Value: 20191219102115 },
            { Name: 'PhoneNumber', Value: 254708374149 },
          ],
        },
      },
    },
  }

  // Failed callback (user cancelled / insufficient funds)
  const failedPayload = {
    Body: {
      stkCallback: {
        MerchantRequestID: '29115-34620561-1',
        CheckoutRequestID: 'ws_CO_191220191020363925',
        ResultCode: 1032, // "Request cancelled by user"
        ResultDesc: 'Request cancelled by user',
      },
    },
  }

  describe('parseCallback', () => {
    test('extracts amount + receipt number from success payload', () => {
      const result = mpesa.parseCallback(successPayload)
      expect(result).not.toBeNull()
      expect(defined(result).amount).toBe(500)
      expect(defined(result).transactionId).toBe('NLJ7RT61SV')
      expect(defined(result).phone).toBe('254708374149')
      expect(defined(result).status).toBe('completed')
    })

    test('returns null for failed callback (no CallbackMetadata)', () => {
      const result = mpesa.parseCallback(failedPayload)
      expect(result).toBeNull()
    })

    test('returns null for malformed payload (missing Body)', () => {
      expect(mpesa.parseCallback({} as Record<string, unknown>)).toBeNull()
      expect(mpesa.parseCallback({ Body: {} } as Record<string, unknown>)).toBeNull()
      expect(mpesa.parseCallback({ Body: { stkCallback: {} } } as Record<string, unknown>)).toBeNull()
    })

    test('handles missing Amount gracefully (returns 0)', () => {
      const payload = {
        Body: {
          stkCallback: {
            ResultCode: 0,
            CallbackMetadata: {
              Item: [{ Name: 'MpesaReceiptNumber', Value: 'ABC123' }],
            },
          },
        },
      }
      const result = mpesa.parseCallback(payload as Record<string, unknown>)
      expect(result).not.toBeNull()
      expect(defined(result).amount).toBe(0)
      expect(defined(result).transactionId).toBe('ABC123')
    })
  })

  describe('amount verification logic (callback route step 7)', () => {
    // This mirrors the logic in callback/route.ts lines 140-168:
    //   const plan = getPlan(planId)
    //   const expectedAmount = plan?.prices?.KES ?? Number(paymentRow.amount) ?? 0
    //   if (paidAmount > 0 && expectedAmount > 0 &&
    //       Math.round(paidAmount) !== Math.round(expectedAmount)) {
    //     // → mark as failed, fraudFlag = 'amount_mismatch'
    //   }

    test('Pro plan has a KES price that can be looked up', () => {
      const plan = getPlan('pro')
      expect(plan).toBeDefined()
      expect(defined(plan).prices?.KES).toBeDefined()
      expect(defined(plan).prices?.KES ?? 0).toBeGreaterThan(0)
    })

    test('matching amount passes verification', () => {
      const plan = getPlan('pro')
      const expectedAmount = defined(plan).prices?.KES ?? 0
      const paidAmount = expectedAmount // exact match

      const matches =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(matches).toBe(false) // false = no mismatch = pass
    })

    test('underpayment (KES 1 for Pro plan) is flagged as mismatch', () => {
      const plan = getPlan('pro')
      const expectedAmount = defined(plan).prices?.KES ?? 0
      const paidAmount = 1 // user pays KES 1 instead of the Pro price

      const isMismatch =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(isMismatch).toBe(true) // true = mismatch = fraud flag
    })

    test('overpayment is also flagged (defensive)', () => {
      const plan = getPlan('pro')
      const expectedAmount = defined(plan).prices?.KES ?? 0
      const paidAmount = expectedAmount * 2

      const isMismatch =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(isMismatch).toBe(true)
