/**
 * METARDU Enterprise Yjs Offline Mesh Network
 * ===========================================
 * Replaces HTTP polling with true Peer-to-Peer CRDTs using WebRTC.
 * Allows surveyors to sync GNSS points locally over Wi-Fi without internet.
 */

import * as Y from 'yjs'
import { WebrtcProvider } from 'y-webrtc'
import { IndexeddbPersistence } from 'y-indexeddb'

export interface PresenceUser {
  userId: string
  userName: string
  color: string
  cursor?: { lat: number; lng: number }
  onlineAt?: string
}

class YjsMeshNetwork {
  private docs: Map<string, Y.Doc> = new Map()
  private providers: Map<string, WebrtcProvider> = new Map()
  private persistences: Map<string, IndexeddbPersistence> = new Map()

  public getDoc(projectId: string): Y.Doc {
    const existing = this.docs.get(projectId)
    if (existing) return existing

    const doc = new Y.Doc()
    this.docs.set(projectId, doc)

    // Offline persistence via IndexedDB
    if (typeof window !== 'undefined' && 'indexedDB' in window) {
      try {
        const persistence = new IndexeddbPersistence(`metardu-sync-${projectId}`, doc)
        this.persistences.set(projectId, persistence)
      } catch {
        // Fallback gracefully if IndexedDB is disabled/blocked in iframe
      }
    }

    // WebRTC Provider for P2P Local LAN sync (using public & local signaling)
    if (typeof window !== 'undefined') {
      try {
        const signalingServers = ['wss://signaling.yjs.dev', 'ws://localhost:4444']
        const customSignaling = process.env.NEXT_PUBLIC_COLLAB_SIGNALING_URL
        if (customSignaling) {
          signalingServers.unshift(customSignaling)
        }

        const provider = new WebrtcProvider(`metardu-mesh-${projectId}`, doc, {
          signaling: signalingServers,
          password: 'metardu-secure-field',
        })
        this.providers.set(projectId, provider)
      } catch {
        // Fallback gracefully if WebRTC is blocked
      }
    }

    return doc
  }

  public getProvider(projectId: string): WebrtcProvider | undefined {
    return this.providers.get(projectId)
  }

  /**
   * Broadcasts a newly captured survey point across all active mesh peers in real time
   */
  public broadcastPoint(projectId: string, point: { id: string; easting: number; northing: number; elevation?: number; code?: string; timestamp?: number }): void {
    const doc = this.getDoc(projectId)
    const yPoints = doc.getMap<unknown>('live_points')
    doc.transact(() => {
      yPoints.set(point.id, {
        ...point,
        timestamp: point.timestamp || Date.now(),
      })
    })
  }

  /**
   * Retrieves all live synchronized points from the project's CRDT document
   */
  public getLivePoints(projectId: string): Array<{ id: string; easting: number; northing: number; elevation?: number; code?: string }> {
    const doc = this.getDoc(projectId)
    const yPoints = doc.getMap<unknown>('live_points')
    const results: Array<{ id: string; easting: number; northing: number; elevation?: number; code?: string }> = []
    yPoints.forEach((val) => {
      if (val && typeof val === 'object') {
        results.push(val as any)
      }
    })
    return results
  }

  public async unsubscribe(projectId: string): Promise<void> {
    const provider = this.providers.get(projectId)
    if (provider) {
      provider.disconnect()
      provider.destroy()
      this.providers.delete(projectId)
    }

    const persistence = this.persistences.get(projectId)
    if (persistence) {
      persistence.destroy()
      this.persistences.delete(projectId)
    }

    const doc = this.docs.get(projectId)
    if (doc) {
      doc.destroy()
      this.docs.delete(projectId)
    }
  }

  public async unsubscribeAll(): Promise<void> {
    for (const projectId of Array.from(this.docs.keys())) {
      await this.unsubscribe(projectId)
    }
  }
}

export const realtimeService = new YjsMeshNetwork()

export function subscribeToProjectChanges(
  projectId: string,
  user: { id: string; email?: string; name?: string },
  callbacks: {
    onPointsChange?: (payload: unknown) => void
    onTraverseChange?: (payload: unknown) => void
    onLevelingChange?: (payload: unknown) => void
    onPresenceChange?: (users: PresenceUser[]) => void
  }
): { unsubscribe: () => Promise<void> } {
  const doc = realtimeService.getDoc(projectId)
  const activeProvider = realtimeService.getProvider(projectId)

  // Listen to points changes
  if (callbacks.onPointsChange) {
    const yPoints = doc.getMap('live_points')
    const handlePointsChange = () => {
      const pts = realtimeService.getLivePoints(projectId)
      callbacks.onPointsChange?.(pts)
    }
    yPoints.observe(handlePointsChange)
  }

  if (activeProvider && callbacks.onPresenceChange) {
    const awareness = activeProvider.awareness

    // Set local presence
    awareness.setLocalStateField('user', {
      userId: user.id,
      userName: user.name || user.email || 'Unknown Surveyor',
      color: '#' + Math.floor(Math.random() * 16777215).toString(16),
      onlineAt: new Date().toISOString(),
    })

    const handleAwarenessChange = () => {
      const states = Array.from(awareness.getStates().values())
      const users = states
        .filter((state: { user?: { userId?: string } }) => state.user && state.user.userId !== user.id)
        .map((state) => state.user as PresenceUser)
      callbacks.onPresenceChange?.(users)
    }

    awareness.on('change', handleAwarenessChange)
    handleAwarenessChange()

    return {
      unsubscribe: async () => {
        awareness.off('change', handleAwarenessChange)
      },
    }
  }

  return {
    unsubscribe: async () => {},
  }
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { subscribeToProjectChanges, PresenceUser, realtimeService } from './index'
import { initProjectSync } from './zustand-yjs-sync'
import type { YArrayEvent } from 'yjs'

export interface Collaborator {
  userId: string
  userName: string
  color: string
  cursor?: { lat: number; lng: number }
}

interface UseCollaborationProps {
  projectId: string | null
  userId?: string
  userName?: string
}

export interface UseCollaborationReturn {
  collaborators: Collaborator[]
  isConnected: boolean
  conflictWarnings: string[]
  livePoints: Array<{ id: string; easting: number; northing: number; elevation?: number; code?: string }>
  broadcastPoint: (point: { id: string; easting: number; northing: number; elevation?: number; code?: string }) => void
  sendCursor: (lat: number, lng: number) => void
  sendFeatureEdit: (feature: { id: string; [key: string]: unknown }) => void
  sendFeatureDelete: (featureId: string) => void
  sendChat: (message: string) => void
  onFeatureEdit?: (feature: { id: string; [key: string]: unknown }, userId: string) => void
  onFeatureDelete?: (featureId: string, userId: string) => void
  onChat?: (message: string, userName: string, userId: string) => void
}

export function useCollaboration({
  projectId,
  userId,
  userName,
}: UseCollaborationProps): UseCollaborationReturn {
  const [collaborators, setCollaborators] = useState<Collaborator[]>([])
  const [livePoints, setLivePoints] = useState<Array<{ id: string; easting: number; northing: number; elevation?: number; code?: string }>>([])
  const [isConnected, setIsConnected] = useState(false)
  const [conflictWarnings] = useState<string[]>([])

  const callbacksRef = useRef<{
    onFeatureEdit?: (feature: { id: string; [key: string]: unknown }, userId: string) => void
    onFeatureDelete?: (featureId: string, userId: string) => void
    onChat?: (message: string, userName: string, userId: string) => void
  }>({})

  useEffect(() => {
    if (!projectId || !userId) return

    // 1. Initialize Zustand-Yjs Data Sync
    initProjectSync(projectId)

    // 2. Initialize Presence via Yjs Awareness and Points Sync
    const subscription = subscribeToProjectChanges(
      projectId,
      { id: userId, name: userName },
      {
        onPresenceChange: (users: PresenceUser[]) => {
          setCollaborators(users.map(u => ({
            userId: u.userId,
            userName: u.userName,
            color: u.color,
            cursor: u.cursor
          })))
        },
        onPointsChange: (pts: unknown) => {
          if (Array.isArray(pts)) {
            setLivePoints(pts as any)
          }
        }
      }
    )

    // Initial points load
    setLivePoints(realtimeService.getLivePoints(projectId))

    // Monitor WebRTC connection state
    const provider = realtimeService.getProvider(projectId)
    if (provider) {
      provider.on('status', ({ connected }: { connected: boolean }) => {
        setIsConnected(connected)
      })
      // If already connected before listener was attached
      setIsConnected(provider.connected)
    }

    return () => {
      subscription.unsubscribe()
    }
  }, [projectId, userId, userName])

  const broadcastPoint = useCallback((point: { id: string; easting: number; northing: number; elevation?: number; code?: string }) => {
    if (!projectId) return
    realtimeService.broadcastPoint(projectId, point)
  }, [projectId])

  // Real-time Chat via Yjs Array
  const sendChat = useCallback((message: string) => {
    if (!projectId || !userId) return
    const doc = realtimeService.getDoc(projectId)
    const yChat = doc.getArray('chat')
    yChat.push([{
      userId,
      userName: userName || 'Unknown',
      message,
      timestamp: Date.now()
    }])
  }, [projectId, userId, userName])

  // Setup Chat Observer
  useEffect(() => {
    if (!projectId) return
    const doc = realtimeService.getDoc(projectId)
    const yChat = doc.getArray('chat')

    const observer = (event: YArrayEvent<unknown>) => {
      event.changes.added.forEach((item) => {
        item.content.getContent().forEach((msg) => {
          const m = msg as { message: string; userName: string; userId: string }
          if (m.userId !== userId) {
            callbacksRef.current.onChat?.(m.message, m.userName, m.userId)
          }
        })
      })
    }

    yChat.observe(observer)
    return () => yChat.unobserve(observer)
  }, [projectId, userId])

  // Mouse Cursor Sharing via Yjs Awareness
  const sendCursor = useCallback((lat: number, lng: number) => {
    if (!projectId || !userId) return
    const provider = realtimeService.getProvider(projectId)
    if (provider) {
      const awareness = provider.awareness
      const localState = awareness.getLocalState() as { user?: { [key: string]: unknown } } | null | undefined
      awareness.setLocalState({
        ...localState,
        user: { ...(localState?.user ?? {}), cursor: { lat, lng } }
      })
    }
  }, [projectId, userId])

  // Feature Edits are now handled automatically by the Zustand-Yjs sync layer.
  // These are kept as no-ops to satisfy the component prop types.
  const sendFeatureEdit = useCallback(() => {}, [])
  const sendFeatureDelete = useCallback(() => {}, [])

  return {
    collaborators,
    isConnected,
    conflictWarnings,
    livePoints,
    broadcastPoint,
    sendCursor,
    sendFeatureEdit,
    sendFeatureDelete,
    sendChat,
    ...callbacksRef.current,
  }
}

/**
 * Kenya precision audit — Survey Act Cap 299 / RDM 1.1 / Survey Regulations 1994
 *
 * Part A: traverse closure classification must match RDM 1.1 Table 2.4
 *         (C = m√K, orders FIRST I … THIRD).
 * Part B: Reg 89 standard plotting scales must cover every area band with no
 *         gaps/overlaps and include the 1:1250 cadastral default.
 */
import { computeTraverseAccuracy, ACCURACY_CLASSES } from '@/lib/reports/traverseAccuracy'
import { STANDARD_SCALES } from '@/lib/survey/surveyRegulationsExtended'

describe('Kenya precision audit — RDM 1.1 Table 2.4 closure classes', () => {
  it('classifies a first-order-class-I traverse (tight closure)', () => {
    // C=0.5mm allowed at K=1km: m√K = 0.5·1 = 0.5mm
    const r = computeTraverseAccuracy(0.0004, 1000)
    expect(r?.order).toBe('FIRST ORDER CLASS I')
    expect(r?.allowed).toBeLessThanOrEqual(0.5)
  })

  it('classifies third order at loose closure', () => {
    // C=4mm, K=4km → allowed = 4/√4 = 2.0mm = exactly THIRD ORDER limit
    const r = computeTraverseAccuracy(0.004, 4000)
    expect(r?.order).toBe('THIRD ORDER')
    expect(r?.allowed).toBeCloseTo(2.0, 5)
  })

  it('scales the allowance by √K, not linearly', () => {
    // Same relative precision: C growing 10× while K grows 100× keeps
    // C/√K constant → identical class and allowance, proving √K scaling.
    const short = computeTraverseAccuracy(0.0005, 1000)    // 0.5mm @ 1km
    const long = computeTraverseAccuracy(0.005, 100000)    // 5mm @ 100km
    expect(short!.allowed).toBeCloseTo(long!.allowed, 5)
    expect(short!.order).toBe(long!.order)
    expect(long!.C_mm).toBeCloseTo(short!.C_mm * 10, 3)
  })

  it('rejects degenerate input', () => {
    expect(computeTraverseAccuracy(NaN, 100)).toBeNull()
    expect(computeTraverseAccuracy(1, 0)).toBeNull()
  })

  it('exposes all five RDM classes in strict m-order', () => {
    const ms = ACCURACY_CLASSES.map((c) => c.m_mm)
    expect(ms).toEqual([...ms].sort((a, b) => a - b))
    expect(ACCURACY_CLASSES.length).toBe(5)
  })
})

describe('Kenya precision audit — Reg 89 standard plotting scales', () => {
  it('includes the 1:1250 cadastral deed-plan default (≤4ha)', () => {
    const s = STANDARD_SCALES.find((x) => x.scale === 1250)
    expect(s).toBeDefined()
    expect(s!.maxAreaHa).toBe(4)
  })

  it('covers all area bands from small plots to perimeter farms without gaps', () => {
    const sorted = [...STANDARD_SCALES].sort((a, b) => a.maxAreaHa - b.maxAreaHa)
    for (let i = 1; i < sorted.length; i++) {
      expect(sorted[i].maxAreaHa).toBeGreaterThan(sorted[i - 1].maxAreaHa)
    }
    expect(sorted[0].scale).toBeLessThanOrEqual(500)   // foundation-scale plots
    expect(sorted[sorted.length - 1].maxAreaHa).toBeGreaterThanOrEqual(100) // farms
  })

  it('always recommends the smallest scale that fits the area', () => {
    const pick = (ha: number) => STANDARD_SCALES.find((s) => ha <= s.maxAreaHa)
    expect(pick(0.05)?.scale).toBe(250)
    expect(pick(3)?.scale).toBe(1250)
    expect(pick(150)).toBeUndefined() // beyond largest standard scale
  })
})

import {
  SpatialRTree,
  SpatialKdTree,
  cullToViewport,
  type SpatialItem,
  type Point2DItem,
} from '../spatialIndex'

describe('High-Capacity Spatial Indexing Engine', () => {
  describe('SpatialRTree (STR Bulk-Loaded 2D R-Tree)', () => {
    test('indexes and searches 50,000 points with sub-millisecond viewport queries', () => {
      const NUM_POINTS = 50000
      const items: SpatialItem<{ id: number; name: string }>[] = []

      // Generate 50,000 points in a 10km x 10km survey block (0 to 10,000m)
      for (let i = 0; i < NUM_POINTS; i++) {
        const x = (i * 73) % 10000
        const y = (i * 137) % 10000
        items.push({
          minX: x,
          minY: y,
          maxX: x,
          maxY: y,
          data: { id: i, name: `PT_${i}` },
        })
      }

      const rtree = new SpatialRTree<{ id: number; name: string }>(32)
      const t0 = performance.now()
      rtree.load(items)
      const loadTime = performance.now() - t0

      expect(rtree.size).toBe(NUM_POINTS)
      expect(loadTime).toBeLessThan(500) // Bulk loads in under 500ms

      // Query a 500m x 500m viewport window in the center (4500 to 5000)
      const tQuery0 = performance.now()
      const results = rtree.search({
        minX: 4500,
        minY: 4500,
        maxX: 5000,
        maxY: 5000,
      })
      const queryTime = performance.now() - tQuery0

      expect(results.length).toBeGreaterThan(0)
      expect(queryTime).toBeLessThan(5) // Sub-5ms query on 50,000 points

      // Verify all returned items are strictly within query box
      for (const res of results) {
        expect(res.minX).toBeGreaterThanOrEqual(4500)
        expect(res.maxX).toBeLessThanOrEqual(5000)
        expect(res.minY).toBeGreaterThanOrEqual(4500)
        expect(res.maxY).toBeLessThanOrEqual(5000)
      }
    })

    test('culls 50,000 points to viewport correctly', () => {
      const items: SpatialItem<{ label: string }>[] = [
        { minX: 100, minY: 100, maxX: 100, maxY: 100, data: { label: 'Inside' } },
        { minX: 9999, minY: 9999, maxX: 9999, maxY: 9999, data: { label: 'Far Away' } },
      ]
      const rtree = new SpatialRTree<{ label: string }>()
      rtree.load(items)

      const visible = cullToViewport(rtree, {
        minE: 50,
        minN: 50,
        maxE: 150,
        maxN: 150,
      })

      expect(visible.length).toBe(1)
      expect(visible[0].label).toBe('Inside')
    })
  })

  describe('SpatialKdTree (2D K-d Tree for Snapping)', () => {
    test('finds exact nearest beacon in O(log N) time', () => {
      const points: Point2DItem<{ beacon: string }>[] = [
        { x: 10, y: 10, data: { beacon: 'BP1' } },
        { x: 50, y: 50, data: { beacon: 'BP2' } },
        { x: 100, y: 100, data: { beacon: 'BP3' } },
        { x: 200, y: 200, data: { beacon: 'BP4' } },
      ]

      const kdTree = new SpatialKdTree(points)
      expect(kdTree.size).toBe(4)

      // Query near BP2 (52, 49)
      const nearest = kdTree.nearest(52, 49)
      expect(nearest).not.toBeNull()
      expect(nearest!.item.data.beacon).toBe('BP2')
      expect(nearest!.distance).toBeCloseTo(Math.hypot(2, -1), 2)
    })

    test('finds all beacons within snap radius', () => {
      const points: Point2DItem<{ id: number }>[] = [
        { x: 100, y: 100, data: { id: 1 } },
        { x: 105, y: 102, data: { id: 2 } },
        { x: 108, y: 95, data: { id: 3 } },
        { x: 500, y: 500, data: { id: 4 } },
      ]

      const kdTree = new SpatialKdTree(points)
      const within15m = kdTree.withinRadius(100, 100, 15)

      expect(within15m.length).toBe(3)
      const ids = within15m.map(w => w.item.data.id)
      expect(ids).toContain(1)
      expect(ids).toContain(2)
      expect(ids).toContain(3)
      expect(ids).not.toContain(4)
    })
  })
})

/**
 * METARDU — High-Performance Spatial Index Engine
 * 
 * Implements:
 * 1. 2D R-Tree with Sort-Tile-Recursive (STR) Bulk-Loading:
 *    Enables O(log N) viewport window queries over 100,000+ points and survey features.
 * 2. 2D K-d Tree:
 *    Enables O(log N) nearest-neighbor snapping and radius searches for beacon selection.
 * 3. Viewport Culler:
 *    Dynamically filters large point clouds down to visible bounds to maintain 60 FPS rendering.
 */

export interface BoundingBox {
  minX: number
  minY: number
  maxX: number
  maxY: number
}

export interface SpatialItem<T = unknown> {
  minX: number
  minY: number
  maxX: number
  maxY: number
  data: T
}

export interface Point2DItem<T = unknown> {
  x: number
  y: number
  data: T
}

// ─── 2D R-TREE IMPLEMENTATION ───────────────────────────────────────────────

interface RTreeNode<T> {
  bbox: BoundingBox
  leaf: boolean
  children: Array<RTreeNode<T> | SpatialItem<T>>
}

export class SpatialRTree<T = unknown> {
  private maxEntries: number
  private root: RTreeNode<T>
  private totalItems: number = 0

  constructor(maxEntries: number = 16) {
    this.maxEntries = Math.max(4, maxEntries)
    this.root = {
      bbox: { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity },
      leaf: true,
      children: [],
    }
  }

  public get size(): number {
    return this.totalItems
  }

  /**
   * Sort-Tile-Recursive (STR) bulk loading algorithm.
   * Builds an optimally packed R-Tree in O(N log N) time with zero overlap.
   */
  public load(items: SpatialItem<T>[]): this {
    this.clear()
    if (items.length === 0) return this

    this.totalItems = items.length

    // Sort by X center
    items.sort((a, b) => (a.minX + a.maxX) / 2 - (b.minX + b.maxX) / 2)

    const N = items.length
    const M = this.maxEntries
    const numLeafNodes = Math.ceil(N / M)
    const numVerticalSlices = Math.ceil(Math.sqrt(numLeafNodes))
    const sliceCapacity = numVerticalSlices * M

    const leafNodes: RTreeNode<T>[] = []

    for (let i = 0; i < N; i += sliceCapacity) {
      const slice = items.slice(i, i + sliceCapacity)
      // Sort slice by Y center
      slice.sort((a, b) => (a.minY + a.maxY) / 2 - (b.minY + b.maxY) / 2)

      for (let j = 0; j < slice.length; j += M) {
        const chunk = slice.slice(j, j + M)
        const nodeBbox = this.computeBounds(chunk)
        leafNodes.push({
          bbox: nodeBbox,
          leaf: true,
          children: chunk,
        })
      }
    }

    // Build higher levels
    let currentLevel = leafNodes
    while (currentLevel.length > 1) {
      const parentLevel: RTreeNode<T>[] = []
      for (let i = 0; i < currentLevel.length; i += M) {
        const chunk = currentLevel.slice(i, i + M)
        parentLevel.push({
          bbox: this.computeBounds(chunk),
          leaf: false,
          children: chunk,
        })
      }
      currentLevel = parentLevel
    }

    this.root = currentLevel[0] || {
      bbox: { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity },
      leaf: true,
      children: [],
    }

    return this
  }

  /**
   * Searches for all items whose bounding box intersects the query bounding box
   */
  public search(queryBox: BoundingBox): SpatialItem<T>[] {
    const results: SpatialItem<T>[] = []
    if (!this.intersects(this.root.bbox, queryBox)) return results

    const stack: RTreeNode<T>[] = [this.root]

    while (stack.length > 0) {
      const node = stack.pop()!
      for (let i = 0; i < node.children.length; i++) {
        const child = node.children[i]
        if (node.leaf) {
          const item = child as SpatialItem<T>
          if (this.intersects(item, queryBox)) {
            results.push(item)
          }
        } else {
          const childNode = child as RTreeNode<T>
          if (this.intersects(childNode.bbox, queryBox)) {
            stack.push(childNode)
          }
        }
      }
    }

    return results
  }

  public clear(): void {
    this.root = {
      bbox: { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity },
      leaf: true,
      children: [],
    }
    this.totalItems = 0
  }

  private intersects(a: BoundingBox, b: BoundingBox): boolean {
    return !(a.maxX < b.minX || a.minX > b.maxX || a.maxY < b.minY || a.minY > b.maxY)
  }

  private computeBounds(entries: Array<RTreeNode<T> | SpatialItem<T>>): BoundingBox {
    let minX = Infinity
    let minY = Infinity
    let maxX = -Infinity
    let maxY = -Infinity

    for (let i = 0; i < entries.length; i++) {
      const e = 'bbox' in entries[i] ? (entries[i] as RTreeNode<T>).bbox : (entries[i] as SpatialItem<T>)
      if (e.minX < minX) minX = e.minX
      if (e.minY < minY) minY = e.minY
      if (e.maxX > maxX) maxX = e.maxX
      if (e.maxY > maxY) maxY = e.maxY
    }

    return { minX, minY, maxX, maxY }
  }
}

// ─── 2D K-D TREE IMPLEMENTATION ─────────────────────────────────────────────

interface KdNode<T> {
  point: Point2DItem<T>
  left: KdNode<T> | null
  right: KdNode<T> | null
}

export class SpatialKdTree<T = unknown> {
  private root: KdNode<T> | null = null
  private count: number = 0

  constructor(points?: Point2DItem<T>[]) {
    if (points && points.length > 0) {
      this.build(points)
    }
  }

  public get size(): number {
    return this.count
  }

  public build(points: Point2DItem<T>[]): void {
    this.count = points.length
    this.root = this.buildRecursive(points.slice(), 0)
  }

  private buildRecursive(pts: Point2DItem<T>[], depth: number): KdNode<T> | null {
    if (pts.length === 0) return null

    const axis = depth % 2 // 0 for X, 1 for Y
    pts.sort((a, b) => (axis === 0 ? a.x - b.x : a.y - b.y))

    const median = Math.floor(pts.length / 2)
    return {
      point: pts[median],
      left: this.buildRecursive(pts.slice(0, median), depth + 1),
      right: this.buildRecursive(pts.slice(median + 1), depth + 1),
    }
  }

  /**
   * Finds the nearest neighbor to (x, y) in O(log N) time
   */
  public nearest(x: number, y: number, maxDistance: number = Infinity): { item: Point2DItem<T>; distance: number } | null {
    if (!this.root) return null

    let bestPoint: Point2DItem<T> | null = null
    let bestDistSq = maxDistance * maxDistance

    const searchNode = (node: KdNode<T> | null, depth: number) => {
      if (!node) return

      const dx = node.point.x - x
      const dy = node.point.y - y
      const dSq = dx * dx + dy * dy

      if (dSq < bestDistSq) {
        bestDistSq = dSq
        bestPoint = node.point
      }

      const axis = depth % 2
      const axisDist = axis === 0 ? x - node.point.x : y - node.point.y

      const first = axisDist < 0 ? node.left : node.right
      const second = axisDist < 0 ? node.right : node.left

      searchNode(first, depth + 1)

      // Only search second branch if it could contain a closer point
      if (axisDist * axisDist < bestDistSq) {
        searchNode(second, depth + 1)
      }
    }

    searchNode(this.root, 0)

    if (!bestPoint) return null
    return { item: bestPoint, distance: Math.sqrt(bestDistSq) }
  }

  /**
   * Finds all points within radius R of (x, y)
   */
  public withinRadius(x: number, y: number, radius: number): Array<{ item: Point2DItem<T>; distance: number }> {
    const results: Array<{ item: Point2DItem<T>; distance: number }> = []
    if (!this.root) return results

    const radiusSq = radius * radius

    const searchNode = (node: KdNode<T> | null, depth: number) => {
      if (!node) return

      const dx = node.point.x - x
      const dy = node.point.y - y
      const dSq = dx * dx + dy * dy

      if (dSq <= radiusSq) {
        results.push({ item: node.point, distance: Math.sqrt(dSq) })
      }

      const axis = depth % 2
      const axisDist = axis === 0 ? x - node.point.x : y - node.point.y

      const first = axisDist < 0 ? node.left : node.right
      const second = axisDist < 0 ? node.right : node.left

      searchNode(first, depth + 1)
      if (axisDist * axisDist <= radiusSq) {
        searchNode(second, depth + 1)
      }
    }

    searchNode(this.root, 0)
    return results
  }
}

// ─── VIEWPORT CULLER HELPER ─────────────────────────────────────────────────

export function cullToViewport<T>(
  spatialTree: SpatialRTree<T>,
  viewportBounds: { minE: number; minN: number; maxE: number; maxN: number },
  bufferRatio: number = 0.1
): T[] {
  const width = viewportBounds.maxE - viewportBounds.minE
  const height = viewportBounds.maxN - viewportBounds.minN
  const bufferE = width * bufferRatio
  const bufferN = height * bufferRatio

  const queryBox: BoundingBox = {
    minX: viewportBounds.minE - bufferE,
    minY: viewportBounds.minN - bufferN,
    maxX: viewportBounds.maxE + bufferE,
    maxY: viewportBounds.maxN + bufferN,
  }

  const items = spatialTree.search(queryBox)
  return items.map(item => item.data)
}
